insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('fr', 'aeolian-islands', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Les Îles Éoliennes (italien : Isole Eolie ; sicilien : Ìsuli Eoli), parfois appelées îles Lipari ou groupe de Lipari d''après leur plus grande île, sont un archipel volcanique de la mer Tyrrhénienne au nord de la Sicile, nommé d''après Éole, le souverain mythique des vents. Les habitants des îles sont connus sous le nom d''Éoliens (italien : Eoliani). Les îles comptaient une population permanente de 14 224 habitants lors du recensement [source datée] ; l''estimation officielle la plus récente est de 15 419 au 1er janvier [source datée]. Les Îles Éoliennes sont une destination touristique populaire en été et attirent jusqu''à 600 000 visiteurs par an.', 'Les îles Éoliennes, parfois appelées îles Lipari d''après la plus grande d''entre elles, forment un archipel volcanique de la mer Tyrrhénienne, au nord de la Sicile. Leur nom viendrait d''Éole, le maître mythique des vents. Leurs habitants sont appelés Éoliens (en italien : Eoliani). L''archipel est une destination estivale très prisée, qui accueille jusqu''à 600 000 visiteurs par an.'),
  ('fr', 'ariege-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'S''étendant sur environ 2 468 km2, il comprend 138 communes depuis le 1er janvier [dated source] et compte 46 000 habitants.', 'Un parc naturel régional d''environ 2 468 km2, qui couvre près de 40 % du département de l''Ariège.'),
  ('fr', 'bieszczady-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'En [source datée], le parc national a été classé au patrimoine mondial de l''UNESCO.', 'Les Bieszczady forment le troisième plus grand parc national de Pologne, à l''extrême sud-est du pays.'),
  ('fr', 'black-forest-central-north-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel de la Forêt-Noire Centre/Nord (en allemand : Naturpark Schwarzwald Mitte/Nord) est situé dans le Bade-Wurtemberg en Allemagne. Il s''étend sur une superficie de 3 750 km² et a été fondé en décembre [source datée]. À la date de [source datée], il s''agit du troisième plus grand parc naturel d''Allemagne.', 'Le parc naturel de la Forêt-Noire centrale et septentrionale (en allemand : Naturpark Schwarzwald Mitte/Nord) se trouve dans le Bade-Wurtemberg, en Allemagne, et couvre 3 750 km2.'),
  ('fr', 'breheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Breheimen National Park est un parc national fondé en [dated source]. Le parc est situé dans les municipalités de Skjåk et de Lom, dans le comté d''Innlandet, ainsi que dans la municipalité de Luster, dans le comté de Vestland, en Norvège. Il s''étend sur 1 671 kilomètres carrés dans la chaîne de montagnes de Breheimen. Le parc englobe certains des terrains les plus humides et les plus secs du pays, avec des paysages façonnés au cours de centaines de milliers d''années par les glaciers, les avalanches et d''autres processus géologiques. Les visiteurs y découvrent tout, des vallées verdoyantes de fermes de transhumance aux plateaux arides, en passant par des sommets vertigineux et des glaciers actifs.', 'Le parc national de Breheimen s''étend sur les communes de Skjåk et de Lom, dans le comté d''Innlandet, et sur celle de Luster, dans le comté de Vestland, en Norvège. Il couvre 1 671 kilomètres carrés du massif de Breheimen, avec certains des terrains les plus humides et les plus secs du pays, façonnés pendant des centaines de milliers d''années par les glaciers, les avalanches et d''autres processus géologiques. On y trouve aussi bien des vallées verdoyantes d''estive que des plateaux arides, des sommets élevés et des glaciers actifs.'),
  ('fr', 'breheimen-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le Breheimen National Park est un parc national fondé en [dated source].', 'Le parc national de Breheimen couvre 1 671 kilomètres carrés du massif de Breheimen, en Norvège.'),
  ('fr', 'catalan-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Créé en mars [source datée], il s''agit du tout premier parc naturel régional de la chaîne des Pyrénées.', 'Premier parc naturel régional des Pyrénées, il couvre le tiers ouest du département des Pyrénées-Orientales.'),
  ('fr', 'caves-of-barac', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Les Caves of Barać, également connues sous le nom de Barać Caves ou grottes de Barać, sont un groupe de grottes situées près du village de Nova Kršlja dans la municipalité de Rakovica, en Croatie. En 1892, les grottes furent ouvertes aux visiteurs avant d''être abandonnées et oubliées après la Seconde Guerre mondiale. En juillet [source datée], les Upper Caves of Barać ont été rouvertes au public.', 'Les grottes de Barać forment un ensemble de grottes près du village de Nova Kršlja, dans la commune de Rakovica, en Croatie. Ouvertes aux visiteurs en 1892, elles furent abandonnées puis oubliées après la Seconde Guerre mondiale. Les grottes supérieures de Barać ont depuis rouvert au public.'),
  ('fr', 'conca-dorupatrimoniogolfe-de-saint-florent', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Conca d''Oru, le vignoble de Patrimonio - golfe de Saint-Florent, a reçu le Label Grand Site de France en mars [source datée]. C’est le dix-septième site labellisé et le second en Corse.', 'La Conca d''Oru, le vignoble de Patrimonio et le golfe de Saint-Florent sont labellisés Grand Site de France. C''est le dix-septième site labellisé et le deuxième en Corse.'),
  ('fr', 'faerder-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Færder National Park est un parc national de la commune de Færder, dans le comté de Vestfold, en Norvège. Il s''agit principalement d''un parc marin, comprenant quelques îles et zones côtières à l''est des grandes îles de Nøtterøy et Tjøme. À l''est, le parc national borde le Ytre Hvaler National Park. Færder couvre une superficie de 340 km2, dont 325 km2 de mer et 15 km2 de terre. Le parc a été créé le 23 août [dated source]. Le parc comprend de grandes parties de l''archipel de Bolærne, ainsi que le phare protégé de Færder et les ruines du phare de Store Færder avec ses bâtiments protégés associés.', 'Le parc national de Færder se trouve dans la commune de Færder, dans le comté de Vestfold, en Norvège. C''est surtout un parc marin, qui comprend des îles et des zones côtières à l''est des grandes îles de Nøtterøy et de Tjøme, et qui jouxte à l''est le parc national d''Ytre Hvaler. Færder couvre 340 km2, dont 325 km2 de mer et 15 km2 de terre. Le parc englobe une grande partie de l''archipel de Bolærne, le phare protégé de Færder et les ruines du phare de Store Færder avec ses bâtiments protégés.'),
  ('fr', 'garrawilla-national-park-nsw', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Garrawilla National Park a été créé en décembre [dated source]. Il couvre une superficie de 937 hectares. Ce parc est situé sur le côté nord de l''Oxley Highway, à mi-chemin environ entre Coonabarabran et Mullaley, en Nouvelle-Galles du Sud, Australie.', 'Le parc national de Garrawilla couvre 937 hectares. Il se trouve au nord de l''Oxley Highway, à mi-chemin environ entre Coonabarabran et Mullaley, en Nouvelle-Galles du Sud (Australie).'),
  ('fr', 'garrawilla-national-park-nsw', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Garrawilla National Park : Garrawilla National Park a été créé en décembre [dated source].', 'Garrawilla National Park : Le parc national de Garrawilla borde l''Oxley Highway entre Coonabarabran et Mullaley (Nouvelle-Galles du Sud).'),
  ('fr', 'garrawilla-national-park-nsw', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Garrawilla National Park a été créé en décembre [dated source].', 'Le parc national de Garrawilla borde l''Oxley Highway entre Coonabarabran et Mullaley (Nouvelle-Galles du Sud).'),
  ('fr', 'grands-causses-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional des Grands Causses est un parc naturel régional français créé le 6 mai 1995 et renouvelé en [dated source]. Situé en Occitanie, à l’extrémité sud du Massif central, il s’étend sur le sud du département de l’Aveyron et le nord de l’Hérault.', 'Le parc naturel régional des Grands Causses a été créé le 6 mai 1995. Situé en Occitanie, à l''extrémité sud du Massif central, il couvre le sud du département de l''Aveyron et le nord de celui de l''Hérault.'),
  ('fr', 'harz-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'En [dated source], le Harz est devenu le premier parc national d''Allemagne à couvrir deux États fédéraux ; la partie orientale en Saxe-Anhalt se compose de 8 900 ha de terres et a été créée en 1990. En 1994, le gouvernement fédéral de Basse-Saxe a établi la partie occidentale du parc, couvrant 15 800 ha. En conséquence, le Harz National Park unifié se compose d''environ 24 700 ha. Le parc fait partie du réseau Natura [dated source] – la conservation de la nature européenne.

Harz National Park s''étend d''une chaîne de basses montagnes près de Herzberg dans la partie sud des montagnes, à travers le massif du Harz jusqu''à ses pentes septentrionales près de Bad Harzburg et Ilsenburg. Il offre toute la gamme des systèmes écologiques caractéristiques, des variations d''altitude, de pentes et de roches. L''altitude varie d''environ 240 m au nord et 270 m sur le bord sud jusqu''à 1 141 m sur le sommet du Brocken. Le parc offre un paysage écologiquement complexe et contient différentes zones de végétation.

Harz National Park est pratiquement inhabité, mais contient quelques colonies. Presque toutes les terres du parc sont boisées et appartiennent aux États fédéraux.

La recherche scientifique a identifié de nombreux habitats qui sont, selon les normes d''Europe centrale, assez proches d''un état naturel, tels que les régions ou zones de haute et moyenne altitude du Harz, les biotopes rocheux, de nombreux cours d''eau et une vaste zone de forêts de hêtres, d''épicéas et mixtes. Dans certaines sections, cependant, des changements écologiques dans le reboisement doivent être effectués afin de se rapprocher des conditions forestières naturelles d''origine.', 'Le parc national du Harz s''étend sur deux Länder : la partie orientale, en Saxe-Anhalt, créée en 1990, compte 8 900 ha, et la partie occidentale, créée par la Basse-Saxe en 1994, couvre 15 800 ha. L''ensemble couvre environ 24 700 ha et fait partie de Natura 2000, le réseau européen de protection de la nature.

Le parc s''étend des collines proches de Herzberg, au sud, à travers le massif du Harz jusqu''à ses versants nord près de Bad Harzburg et d''Ilsenburg. Il réunit toute la gamme des écosystèmes, des altitudes, des pentes et des roches caractéristiques, d''environ 240 m au nord et 270 m au sud jusqu''à 1 141 m au sommet du Brocken, avec plusieurs étages de végétation.

Le parc est presque inhabité, même s''il compte quelques hameaux. Presque toutes ses terres sont boisées et appartiennent aux Länder.

Les recherches ont mis en évidence de nombreux habitats proches de l''état naturel selon les critères d''Europe centrale : les étages supérieur et moyen du Harz, des biotopes rocheux, de nombreux cours d''eau et une vaste forêt de hêtres, d''épicéas et de forêts mixtes. Dans certains secteurs, une gestion forestière reste toutefois nécessaire pour retrouver des conditions plus proches de la forêt naturelle d''origine.'),
  ('fr', 'hump-ridge-track', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Hump Ridge Track, également appelé Tuatapere Hump Ridge Track, est un sentier de randonnée de 60–62 km situé en partie dans le Fiordland National Park en Nouvelle-Zélande. Le sentier a été ouvert en [dated source] et est géré de manière privée au nom du Tuatapere Hump Ridge Track Charitable Trust.', 'Le Hump Ridge Track, aussi appelé Tuatapere Hump Ridge Track, est un sentier de randonnée de 60 à 62 km qui traverse en partie le parc national de Fiordland, en Nouvelle-Zélande. Il est géré de façon privée pour le compte du Tuatapere Hump Ridge Track Charitable Trust.'),
  ('fr', 'jizerskohorske-buciny', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'La forêt de hêtres des montagnes de la Jizera est une réserve naturelle nationale, créée le 16 août 1999 par la fusion des sept réserves naturelles nationales d''origine Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantský cimmburi et Paličík par le décret n° 200 / 1999. En juillet [source datée], elles sont devenues le premier monument naturel tchèque inscrit sur la liste du patrimoine mondial de l''UNESCO.', 'Les hêtraies des monts de la Jizera (Jizerskohorské bučiny) forment une réserve naturelle nationale créée le 16 août 1999 par la fusion de sept réserves : Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantské cimbuří et Paličník. Elles ont été le premier site naturel tchèque inscrit au patrimoine mondial de l''UNESCO.'),
  ('fr', 'junkerdal-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Junkerdal National Park : Le parc de 682 kilomètres carrés a ouvert en [dated source].', 'Junkerdal National Park : Un parc national de 682 km2 à Saltdal et Fauske, dans le comté de Nordland, le long de la frontière suédoise.'),
  ('fr', 'junkerdal-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc de 682 kilomètres carrés a ouvert en [dated source].', 'Un parc national de 682 km2 à Saltdal et Fauske, dans le comté de Nordland, le long de la frontière suédoise.'),
  ('fr', 'kosterhavet-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Kosterhavet National Park est le premier parc marin national de Suède, inauguré en septembre [dated source]. Il fait partie de la mer Skagerrak et est situé dans les municipalités de Strömstad et Tanum dans le Bohuslän, comté de Västra Götaland, Suède. Il se compose de la mer et des rivages autour des îles Koster, à l''exclusion de tout le reste sur les îles. Au nord, il borde le parc marin norvégien d''Ytre Hvaler.', 'Le parc national de Kosterhavet est le premier parc national marin de Suède. Il fait partie du Skagerrak et s''étend sur les communes de Strömstad et de Tanum, dans le Bohuslän (comté de Västra Götaland). Il comprend la mer et les rivages autour des îles Koster, à l''exclusion du reste des îles, et jouxte au nord le parc marin norvégien d''Ytre Hvaler.'),
  ('fr', 'kotychi-and-strofylia-wetlands-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Kotychi and Strofylia Wetlands National Park : Il a été déclaré parc national en [dated source].', 'Kotychi and Strofylia Wetlands National Park : Zones humides et forêt protégées d''Achaïe et d''Élide : lac de Kotychi, forêt de Strofylia, cap Araxos.'),
  ('fr', 'kotychi-and-strofylia-wetlands-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il a été déclaré parc national en [dated source].', 'Zones humides et forêt protégées d''Achaïe et d''Élide : lac de Kotychi, forêt de Strofylia, cap Araxos.'),
  ('fr', 'langsua-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Langsua National Park a été établi en [dated source]. Le parc se compose d''une zone protégée totale de 537.1-square-kilometre . Il est situé dans le comté d''Innlandet en Norvège, et couvre des parties des municipalités de Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron et Nord-Fron.', 'Le parc national de Langsua protège 537,1 kilomètres carrés dans le comté d''Innlandet, en Norvège, sur une partie des communes d''Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron et Nord-Fron.'),
  ('fr', 'langsua-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Langsua National Park : Langsua National Park a été établi en [dated source].', 'Langsua National Park : Le parc national de Langsua protège 537,1 kilomètres carrés dans le comté d''Innlandet, en Norvège.'),
  ('fr', 'langsua-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Langsua National Park a été établi en [dated source].', 'Le parc national de Langsua protège 537,1 kilomètres carrés dans le comté d''Innlandet, en Norvège.'),
  ('fr', 'les-deux-caps-blanc-nez-gris-nez', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Les Deux-Caps Blanc-Nez, Gris-Nez : En [dated source], son périmètre passe de huit à dix-sept municipalités.', 'Les Deux-Caps Blanc-Nez, Gris-Nez : Un Grand Site de France sur la Côte d''Opale, entre Boulogne-sur-Mer et Calais, face à l''Angleterre.'),
  ('fr', 'les-deux-caps-blanc-nez-gris-nez', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'En [dated source], son périmètre passe de huit à dix-sept municipalités.', 'Un Grand Site de France sur la Côte d''Opale, entre Boulogne-sur-Mer et Calais, face à l''Angleterre.'),
  ('fr', 'liechtensteinklamm', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Liechtensteinklamm est ouvert tous les jours de début mai au 30 septembre [dated source] de 09:00 à 18:00 (dernière admission à 18:00).', ''),
  ('fr', 'liechtensteinklamm', 'metaDescription', 'fields', '{metaDescription}'::text[], 'CLEAR', 'Liechtensteinklamm : Liechtensteinklamm est ouvert tous les jours du début mai au 30 septembre [source datée] de 09h00 à 18h00 (dernière', ''),
  ('fr', 'liechtensteinklamm', 'tagline', 'fields', '{tagline}'::text[], 'CLEAR', 'Liechtensteinklamm est ouvert tous les jours du début mai au 30 septembre [source datée] de 09h00 à 18h00 (dernière', ''),
  ('fr', 'lierne-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lierne National Park se situe dans la municipalité de Lierne, dans le comté de Trøndelag, en Norvège. Le parc de 333 kilomètres carrés a été établi le 17 décembre [dated source] par une résolution royale. Le parc couvre 333 kilomètres carrés de terres le long de la frontière avec la Suède. Le parc se situe à l''est des zones habitées de la municipalité de Lierne, à environ 12 kilomètres au sud-est du village de Sandvika et à environ 6 kilomètres au nord-est du village de Mebygda.', 'Le parc national de Lierne se trouve dans la commune de Lierne, dans le comté de Trøndelag, en Norvège. Il couvre 333 kilomètres carrés le long de la frontière suédoise, à l''est des zones habitées de Lierne, à environ 12 kilomètres au sud-est du village de Sandvika et à 6 kilomètres au nord-est de Mebygda.'),
  ('fr', 'lomsdal-visten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Lomsdal–Visten National Park est un parc national norvégien qui a été créé le 26 juin [source datée]. Le parc consiste en une zone protégée totale de 1 102 kilomètres carrés. Il est situé dans le comté de Nordland, en Norvège, et couvre des parties de la municipalité de Brønnøy, de la municipalité de Vevelstad, de la municipalité de Grane et de la municipalité de Vefsn.', 'Le parc national de Lomsdal-Visten est un parc national norvégien d''une superficie protégée de 1 102 kilomètres carrés. Il se trouve dans le comté de Nordland et s''étend sur une partie des communes de Brønnøy, Vevelstad, Grane et Vefsn.'),
  ('fr', 'loonse-en-drunense-duinen', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Loonse en Drunense Duinen : Il est désigné comme parc national depuis [dated source].', 'Loonse en Drunense Duinen : Un parc national de 35 km2 entre Tilburg, Waalwijk et Bois-le-Duc, dans le sud des Pays-Bas.'),
  ('fr', 'loonse-en-drunense-duinen', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il est désigné comme parc national depuis [dated source].', 'Un parc national de 35 km2 entre Tilburg, Waalwijk et Bois-le-Duc, dans le sud des Pays-Bas.'),
  ('fr', 'lorship-bertiz-natural-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Lorship Bertiz Natural Park : Le Natural Park Señorío de Bertiz (officiellement Bertizko Jaurerria Parke Naturala) [dated source] ha, se situ', 'Lorship Bertiz Natural Park : Le Señorío de Bertiz est un parc naturel du nord-ouest de la Navarre, en Espagne, déclaré en 1984.'),
  ('fr', 'lorship-bertiz-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le Natural Park Señorío de Bertiz (officiellement Bertizko Jaurerria Parke Naturala) [dated source] ha, se situ', 'Le Señorío de Bertiz est un parc naturel du nord-ouest de la Navarre, en Espagne, déclaré en 1984.'),
  ('fr', 'marine-natural-park-of-picardy-and-opale-coast', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel marin des estuaires picards et de la mer d''Opale est un parc naturel marin français créé en décembre [dated source]. Il est situé face aux sept fleuves côtiers, du sud au nord, la Bresle, la Somme, l''Authie, la Canche, la Liane, le Wimereux et la Slack. Son siège social est situé à Écault sur le territoire de Saint-Étienne-au-Mont, dans le Pas-de-Calais.', 'Le parc naturel marin des estuaires picards et de la mer d''Opale s''étend au large de sept fleuves côtiers : du sud au nord, la Bresle, la Somme, l''Authie, la Canche, la Liane, le Wimereux et la Slack. Son siège se trouve à Écault, sur la commune de Saint-Étienne-au-Mont (Pas-de-Calais).'),
  ('fr', 'marker-wadden-in-het-markermeer', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Marker Wadden in het Markermeer : La première île a été inaugurée le 24 septembre [dated source].', 'Marker Wadden in het Markermeer : Les Marker Wadden sont un archipel artificiel et une réserve naturelle du lac Markermeer, aux Pays-Bas.'),
  ('fr', 'marker-wadden-in-het-markermeer', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'La première île a été inaugurée le 24 septembre [dated source].', 'Les Marker Wadden sont un archipel artificiel et une réserve naturelle du lac Markermeer, aux Pays-Bas.'),
  ('fr', 'midden-delfland', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Midden-Delfland (en néerlandais : [ˌmɪdəˈdɛlflɑnt] ) est une municipalité de la région du Westland dans la province de Hollande-Méridionale aux Pays-Bas. Elle comptait une population de 19 355 habitants en [source datée] et couvre une superficie de 49,38 km2 dont 2,19 km2 d''eau.', 'Midden-Delfland est une commune de la région du Westland, dans la province de Hollande-Méridionale, aux Pays-Bas. Elle couvre 49,38 km2, dont 2,19 km2 d''eau.'),
  ('fr', 'midden-delfland', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Midden-Delfland : Il comptait une population de 19 355 habitants en [dated source] et couvre une superficie de 49,38 km2, dont 2,19 km2 d''eau.', 'Midden-Delfland : Midden-Delfland est une commune de 49,38 km2 située dans la région du Westland, en Hollande-Méridionale.'),
  ('fr', 'midden-delfland', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il comptait une population de 19 355 habitants en [dated source] et couvre une superficie de 49,38 km2, dont 2,19 km2 d''eau.', 'Midden-Delfland est une commune de 49,38 km2 située dans la région du Westland, en Hollande-Méridionale.'),
  ('fr', 'mont-ventoux', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional du Mont-Ventoux, en provençal pargue dóu Ventours, est un parc naturel régional créé par décret le 28 juillet [dated source]. C''est le 55e parc naturel régional créé en France, et le 9e en Provence-Alpes-Côte d''Azur.', 'Le parc naturel régional du Mont-Ventoux (en provençal : pargue dóu Ventours) est le 55e parc naturel régional créé en France et le 9e en Provence-Alpes-Côte d''Azur.'),
  ('fr', 'mors-and-hanklit', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mors ou Morsø est une île située dans le détroit peu profond appelé Limfjorden, entre la péninsule du Jutland au Danemark et l''île de Vendsyssel-Thy (North Jutlandic Island). Elle a une superficie de 367,3 km2 et, au 1er janvier [dated source], elle comptait une population de 19 486 habitants. La ville principale de l''île s''appelle Nykøbing Mors. Sur le plan géologique, Mors est unique. Comme l''île voisine de Fur, elle est connue pour ses gisements de diatomite, localement appelés « moler ».', 'Mors (Morsø) est une île du Limfjord, le détroit peu profond qui sépare la péninsule du Jutland de l''île de Vendsyssel-Thy, au Danemark. Elle couvre 367,3 km2 et sa ville principale est Nykøbing Mors. Sur le plan géologique, Mors est unique : comme l''île voisine de Fur, elle est connue pour ses gisements de diatomite, appelée localement « moler ».'),
  ('fr', 'mors-and-hanklit', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Mors and Hanklit : Il a une superficie de 367,3 km2 et, au 1er janvier [source datée], il comptait 19 486 habitants.', 'Mors and Hanklit : Mors est une île de 367,3 km2 dans le Limfjord, au Danemark, connue pour ses gisements de diatomite (moler).'),
  ('fr', 'mors-and-hanklit', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il a une superficie de 367,3 km2 et, au 1er janvier [source datée], il comptait 19 486 habitants.', 'Mors est une île de 367,3 km2 dans le Limfjord, au Danemark, connue pour ses gisements de diatomite (moler).'),
  ('fr', 'morskie-oko', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Morskie Oko, ou l''Œil de la Mer en français, est le plus grand et le quatrième lac le plus profond des montagnes des Tatras, dans le sud de la Pologne. Il est situé au cœur du Tatra National Park, dans la vallée de Rybi Potok, au sein de la chaîne des Hautes Tatras, au pied des sommets Mięguszowiecki, dans la voïvodie de Petite-Pologne. En [dated source], le Wall Street Journal a reconnu le lac comme l''un des cinq plus beaux lacs du monde.', 'Le Morskie Oko (« l''Œil de la mer ») est le plus grand et le quatrième plus profond lac des Tatras, dans le sud de la Pologne. Il se trouve au cœur du parc national des Tatras, dans la vallée de Rybi Potok, dans les Hautes Tatras, au pied des sommets Mięguszowiecki, en Petite-Pologne.'),
  ('fr', 'nationaal-park-de-sallandse-heuvelrug', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Nationaal Park De Sallandse Heuvelrug : En [dated source], le gouvernement néerlandais a changé le statut de la zone en Parc National.', 'Nationaal Park De Sallandse Heuvelrug : La Sallandse Heuvelrug est un parc national de l''Overijssel, entre les communes de Hellendoorn et de Holten.'),
  ('fr', 'nationaal-park-de-sallandse-heuvelrug', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'En [dated source], le gouvernement néerlandais a changé le statut de la zone en Parc National.', 'La Sallandse Heuvelrug est un parc national de l''Overijssel, entre les communes de Hellendoorn et de Holten.'),
  ('fr', 'nationaal-park-duinen-van-texel', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Nationaal Park Duinen van Texel : Le parc couvre environ 43 km2 et a obtenu le statut de parc national en [source datée].', 'Nationaal Park Duinen van Texel : Le parc national Duinen van Texel couvre environ 43 km2 de dunes et de plaines côtières sur l''île de Texel.'),
  ('fr', 'nationaal-park-duinen-van-texel', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc couvre environ 43 km2 et a obtenu le statut de parc national en [source datée].', 'Le parc national Duinen van Texel couvre environ 43 km2 de dunes et de plaines côtières sur l''île de Texel.'),
  ('fr', 'national-park-drina', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Drina National Park est le quatrième parc national de Bosnie-Herzégovine, et le troisième de la Republika Srpska. Il a été fondé en [dated source]. La ville la plus proche est Srebrenica. Il est situé de l''autre côté de la Drina par rapport au Tara National Park en Serbie.', 'Le parc national de la Drina est le quatrième parc national de Bosnie-Herzégovine et le troisième de la République serbe de Bosnie. La ville la plus proche est Srebrenica. Il se trouve sur la rive opposée de la Drina, face au parc national de Tara, en Serbie.'),
  ('fr', 'national-park-of-eastern-macedonia-and-thrace', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le National Park of Eastern Macedonia - Thrace a été fondé en [dated source] et incluait les zones déjà protégées de D. Nestos, L. Vistonidas, L. Ismaridas et leur zone élargie. Le complexe de zones humides du parc national est l''un des plus importants de Grèce, en raison de sa vaste superficie et de sa grande valeur biologique, esthétique, scientifique, géomorphologique et pédagogique. L''objectif du parc national est de protéger efficacement les habitats et les espèces rares de flore et de faune endémiques et reproductrices dans la région.', 'Le parc national de Macédoine-Orientale-et-Thrace englobe le delta du Nestos, le lac Vistonida, le lac Ismarida, déjà protégés, ainsi que leurs environs. Son complexe de zones humides est l''un des plus importants de Grèce par sa superficie et sa grande valeur biologique, paysagère, scientifique, géomorphologique et pédagogique. Le parc vise à protéger les habitats et les espèces rares de flore et de faune endémiques ou nicheuses de la région.'),
  ('fr', 'national-park-of-messolonghi-aitoliko-lagoons', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'National Park of Messolonghi - Aitoliko lagoons : Créé en [dated source], il englobe le plus grand complexe lagunaire du pays.', 'National Park of Messolonghi - Aitoliko lagoons : Le parc national englobe le plus grand complexe lagunaire de Grèce, au nord-ouest du golfe de Patras.'),
  ('fr', 'national-park-of-messolonghi-aitoliko-lagoons', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Créé en [dated source], il englobe le plus grand complexe lagunaire du pays.', 'Le parc national englobe le plus grand complexe lagunaire de Grèce, au nord-ouest du golfe de Patras.'),
  ('fr', 'nationalpark-thy', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Thy National Park est une zone de parc national située à Thy, au Danemark, ouverte au public le 22 août [dated source]. Il est situé dans le nord-ouest du Jutland, le long de la côte de Hanstholm à Agger Tange, et s''étend sur 55 km du nord au sud et sur 5 à 12 km d''est en ouest. La superficie totale du parc national est de 244 km2.', 'Le parc national de Thy se trouve dans la région de Thy, au Danemark. Il s''étend dans le nord-ouest du Jutland, le long de la côte de Hanstholm à Agger Tange, sur 55 km du nord au sud et 5 à 12 km d''est en ouest. Sa superficie totale est de 244 km2.'),
  ('fr', 'natural-park-of-serra-d-irta', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Serra d''Irta Natural Park (Valencien : Parc Natural de la Serra d''Irta, Espagnol : Parque Natural de la Sierra de Irta) est un parc naturel de la Communauté valencienne, au sud de l''Espagne. Il contient 7 744 hectares de terres, ainsi qu''un littoral de réserve naturelle marine de la mer Méditerranée adjacente. Il a été déclaré zone protégée en [dated source].', 'Le parc naturel de la Serra d''Irta (en valencien : Parc Natural de la Serra d''Irta ; en espagnol : Parque Natural de la Sierra de Irta) se trouve dans la Communauté valencienne, en Espagne. Il couvre 7 744 hectares de terres ainsi qu''une réserve naturelle marine le long du littoral méditerranéen voisin.'),
  ('fr', 'naturpark-nissum-fjord', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel Nissum Fjord a été mis en place comme projet pilote à la demande du Nissum Fjord Network en mai [dated source]. Le parc naturel s''étend sur 22 670 hectares autour de Nissum Fjord et est le troisième plus grand parc naturel du Danemark. Le parc naturel a été approuvé par le Open Air Council le 12 décembre [dated source].', 'Le parc naturel du Nissum Fjord s''étend sur 22 670 hectares autour du Nissum Fjord ; c''est le troisième plus grand parc naturel du Danemark.'),
  ('fr', 'naturpark-nissum-fjord', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Naturpark Nissum Fjord : Le parc naturel a été approuvé par le Open Air Council le 12 décembre [dated source].', 'Naturpark Nissum Fjord : Le parc naturel du Nissum Fjord couvre 22 670 hectares autour du fjord ; c''est le troisième du Danemark.'),
  ('fr', 'naturpark-nissum-fjord', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc naturel a été approuvé par le Open Air Council le 12 décembre [dated source].', 'Le parc naturel du Nissum Fjord couvre 22 670 hectares autour du fjord ; c''est le troisième du Danemark.')
